import{_ as o,C as n,o as i,c as s,j as t,a as r,E as c,a6 as d}from"./chunks/framework.DIp0zHSV.js";const l="/dev/releases/2026.04.11.2/image-layers.webp",h="/dev/releases/2026.04.11.2/icon-area-zones.webp",w=JSON.parse('{"title":"LCARdS 2026.04.11.2","description":"Image layers for textures and backgrounds, icon-area text zones, on_entity_change conditions.","frontmatter":{"version":"2026.04.11.2","date":"2026-04-11T00:00:00.000Z","status":"released","summary":"Image layers for textures and backgrounds, icon-area text zones, on_entity_change conditions.","breaking":true},"headers":[],"relativePath":"releases/2026.04.11.2.md","filePath":"releases/2026.04.11.2.md","lastUpdated":1791928403000}'),u={name:"releases/2026.04.11.2.md"};function g(p,e,m,f,b,y){const a=n("ReleaseMeta");return i(),s("div",null,[e[0]||(e[0]=t("h1",{id:"lcards-2026-04-11-2",tabindex:"-1"},[r("LCARdS 2026.04.11.2 "),t("a",{class:"header-anchor",href:"#lcards-2026-04-11-2","aria-label":'Permalink to "LCARdS 2026.04.11.2"'},"​")],-1)),c(a),e[1]||(e[1]=d('<h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="image-support" tabindex="-1">Image Support <a class="header-anchor" href="#image-support" aria-label="Permalink to &quot;Image Support&quot;">​</a></h3><p>Image support has been added to both card Textures and Backgrounds (<a href="https://github.com/snootched/lcards/issues/336" target="_blank" rel="noreferrer">#336</a>)<br> You can configure images as layers, just like you do animations. Just like any layer, they can be stacked with the others, allowing for some interesting and creative visuals. Select builtin images from the asset library, or provide your own (served from a local Home Assistant or any URL)</p><img class="release-shot" alt="Card with stacked image and animation layers" src="'+l+'"><p><strong>Asset Library - Images</strong> - raster image type has been added to the Asset Library system, and some freely distributable images are included as a bultin content pack.</p><h3 id="text-zones-icon-area-support" tabindex="-1">Text Zones - Icon Area Support <a class="header-anchor" href="#text-zones-icon-area-support" aria-label="Permalink to &quot;Text Zones - Icon Area Support&quot;">​</a></h3><p>Text zones will now auto-calculate and respect icon areas (<a href="https://github.com/snootched/lcards/issues/335" target="_blank" rel="noreferrer">#335</a>)<br> Now you can place text fields in the icon area (<code>icon</code>), in the body/content area (<code>body</code>), or anywhere on the full card (<code>full</code>):</p><img class="release-shot" alt="Text zones around a button icon area" src="'+h+'"><h3 id="animations-on-entity-change-trigger-condition-system" tabindex="-1">Animations: <code>on_entity_change</code> trigger condition system <a class="header-anchor" href="#animations-on-entity-change-trigger-condition-system" aria-label="Permalink to &quot;Animations: `on_entity_change` trigger condition system&quot;">​</a></h3><p>The <code>on_entity_change</code> animation trigger now supports three condition modes, turning it from a simple &quot;fire on every change&quot; event into a proper lifecycle-aware animation gate:</p><p><strong><code>from_state</code> / <code>to_state</code></strong> - are single-use fire-and-forget guards. The animation only plays when the entity transitions from a specific state, to a specific state, or both. Great for one-shot effects like a flash when a light turns on.</p><p><strong><code>while</code></strong> - ongoing lifecycle condition. Combined with <code>loop: true</code>, the animation starts automatically when the condition becomes true and stops itself when it clears. Perfect for looping alerts or indicators that should run exactly as long as a condition holds (e.g. blink while a switch is on, when there is a weather alert, etc.)</p><p><strong><code>check_on_load</code></strong>: evaluates the condition against the entity&#39;s current state on card load, so a looping animation starts immediately if the condition is already met rather than waiting for the next state change.</p><p><strong><code>attribute</code></strong> - any condition can target an attribute instead of the main state, including the virtual helper attribute <code>brightness_pct</code> which allows for checking light brightness based on percent.</p><p><strong>vs. the Rules Engine</strong>: use <code>on_entity_change</code> conditions for animation-only, single-entity logic that lives entirely within one card&#39;s config. Use Rules for anything that needs to apply style patches (colors, borders) across multiple overlays or evaluate multi-entity compound conditions. For a simple &quot;blink this button while active&quot;, the trigger conditions are less config than a full rule.</p><h2 id="updates-fixes" tabindex="-1">Updates &amp; Fixes <a class="header-anchor" href="#updates-fixes" aria-label="Permalink to &quot;Updates &amp; Fixes&quot;">​</a></h2><ul><li>Update: Card <code>overflow: visible</code> is honoured preventing clipped animations if the card is scaled outside its bounds.</li><li>Update: Sound System: remove browser localStorage fallback and only use the back-end storage via WebSocket to the integration.</li><li>Update: enabled virtual attriubute <code>brightness_pct</code> to be used available to all cards via the state resolution system. This allows to easily reference light brightness as a percentage <code>[0..100]</code> without the need of mapping the range <code>[0..255]</code></li><li>Fix: Elbow card using <code>frame</code> preset now properly clips the texture layer to the shape (preventing overlap with content/background area)</li><li>Fix: RulesEngine - various fixes including streamlined entity management by removing cached entity list and utilizing live dependency index. Additional console debug commands added.</li><li>Fix: drag&amp;drop in animations editor lists.</li><li>Fix: Animations: fixed regression for <code>ease</code>/<code>easing</code> parameter confusion. Fixed animation parameters for top-level config keys that were buried in the <code>params</code> object (and non-functional, like <code>ease</code>) <br><strong>Note:</strong> due to the nature of the bugs in the animation system and the required fixes - your animation configs may need to be updated. The editor will automatically fix the configs if you edit the animation and make a change to them (the edit fires the code that will write the fixed configurations.)</li></ul><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.04.6.1...2026.04.11.2" target="_blank" rel="noreferrer">2026.04.6.1...2026.04.11.2</a></p>',19))])}const x=o(u,[["render",g]]);export{w as __pageData,x as default};
